diff --git a/git/lock.go b/git/lock.go
index 61f223c..04f04e7 100644
--- a/git/lock.go
+++ b/git/lock.go
@@ -99,7 +99,7 @@ func (l *Lock) Acquire() (LockResult, error) {
 			return LockResult{}, err
 		}
 		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
-			pid := lockPID(f)
+			pid := positivePID(lockPID(f))
 			f.Close()
 			if errors.Is(err, syscall.EWOULDBLOCK) {
 				return LockResult{Status: Held, PID: pid}, nil
@@ -187,6 +187,11 @@ func (l *Lock) Release() {
 // LockOwner reads the diagnostics of the lock at path: the owner's pid and token ("" when
 // absent or written by an earlier Kogen) and whether a running process holds it.
 func LockOwner(path string) (pid, token string, held bool) {
+	pid, token, held = lockOwner(path)
+	return positivePID(pid), token, held
+}
+
+func lockOwner(path string) (pid, token string, held bool) {
 	held, _ = NewLock(path).Held()
 	if st, err := os.Lstat(path); err == nil && st.IsDir() {
 		pid, _, _ = NewLock(path).legacyDirectory(false)
@@ -268,6 +273,19 @@ func lockPID(f *os.File) string {
 	return ""
 }

+// positivePID is s when it is a positive decimal integer and "" otherwise.
+func positivePID(s string) string {
+	for _, r := range s {
+		if r < '0' || r > '9' {
+			return ""
+		}
+	}
+	if n, err := strconv.Atoi(s); err != nil || n <= 0 {
+		return ""
+	}
+	return s
+}
+
 func sameFile(f *os.File, path string) bool {
 	a, err1 := f.Stat()
 	b, err2 := os.Stat(path)
@@ -327,7 +345,11 @@ func AcquireBuild(root string, s *sys.Session) (*Lock, error) {
 	case RemovedStale:
 		s.Progress("kogen: removed the lock of a Build that is no longer running")
 	case Held:
-		return nil, sys.Fail("environment", "build_running", "a Build is running in this repository (pid "+res.PID+")", 3)
+		pid := res.PID
+		if pid == "" {
+			pid = "not recorded"
+		}
+		return nil, sys.Fail("environment", "build_running", "a Build is running in this repository (pid "+pid+")", 3)
 	}
 	return l, nil
 }

